    31→/**
    32→ */
    33→@JsonTypeInfo(use = JsonTypeInfo.Id.NAME, property = "type")
    34→@JsonSubTypes(value = {
    35→    @JsonSubTypes.Type(name = "and", value = AndDimFilter.class),
    36→    @JsonSubTypes.Type(name = "or", value = OrDimFilter.class),
    37→    @JsonSubTypes.Type(name = "not", value = NotDimFilter.class),
    38→    @JsonSubTypes.Type(name = "selector", value = SelectorDimFilter.class),
    39→    @JsonSubTypes.Type(name = "columnComparison", value = ColumnComparisonDimFilter.class),
    40→    @JsonSubTypes.Type(name = "extraction", value = ExtractionDimFilter.class),
    41→    @JsonSubTypes.Type(name = "regex", value = RegexDimFilter.class),
    42→    @JsonSubTypes.Type(name = "search", value = SearchQueryDimFilter.class),
    43→    @JsonSubTypes.Type(name = "javascript", value = JavaScriptDimFilter.class),
    44→    @JsonSubTypes.Type(name = "spatial", value = SpatialDimFilter.class),
    45→    @JsonSubTypes.Type(name = "in", value = InDimFilter.class),
    46→    @JsonSubTypes.Type(name = "bound", value = BoundDimFilter.class),
    47→    @JsonSubTypes.Type(name = "interval", value = IntervalDimFilter.class),
    48→    @JsonSubTypes.Type(name = "like", value = LikeDimFilter.class),
    49→    @JsonSubTypes.Type(name = "expression", value = ExpressionDimFilter.class),
    50→    @JsonSubTypes.Type(name = "true", value = TrueDimFilter.class),
    51→    @JsonSubTypes.Type(name = "false", value = FalseDimFilter.class)
    52→})
    53→public interface DimFilter extends Cacheable
    54→{
    55→  /**
    56→   * @return Returns an optimized filter.
    57→   * returning the same filter can be a straightforward default implementation.
    58→   */
    59→  DimFilter optimize();
    60→
    61→  /**
    62→   * @return Return a Filter that implements this DimFilter, after applying optimizations to this DimFilter.
    63→   * A typical implementation will return the result of `optimize().toFilter()`
    64→   * See abstract base class {@link AbstractOptimizableDimFilter} for a common implementation shared by
    65→   * current DimFilters.
    66→   *
    67→   * The Filter returned by this method across multiple calls must be the same object: parts of the query stack
    68→   * compare Filters, and returning the same object allows these checks to avoid deep comparisons.
    69→   * (see {@link org.apache.druid.segment.join.HashJoinSegmentStorageAdapter#makeCursors for an example}
    70→   */
    71→  Filter toOptimizedFilter();
    72→
    73→  /**
    74→   * Returns a Filter that implements this DimFilter. This does not generally involve optimizing the DimFilter,
    75→   * so it does make sense to optimize first and then call toFilter on the resulting DimFilter.
    76→   *
    77→   * @return a Filter that implements this DimFilter, or null if this DimFilter is a no-op.
    78→   */
    79→  Filter toFilter();
    80→
    81→  /**
    82→   * Returns a RangeSet that represents the possible range of the input dimension for this DimFilter.This is
    83→   * applicable to filters that use dimensions such as select, in, bound, and logical filters such as and, or, not.
    84→   *
    85→   * Null represents that the range cannot be determined, and will be returned for filters such as javascript and regex
    86→   * where there's no easy way to determine the filtered range. It is treated the same way as an all range in most
    87→   * cases, however there are some subtle difference at logical filters such as not filter, where complement of all
    88→   * is nothing while complement of null is still null.
    89→   *
    90→   * @param dimension name of the dimension to get range for
    91→   * @return a RangeSet that represent the possible range of the input dimension, or null if it is not possible to
    92→   * determine for this DimFilter.
    93→   */
    94→  @Nullable
    95→  RangeSet<String> getDimensionRangeSet(String dimension);
    96→
    97→  /**
    98→   * @return a HashSet that represents all columns' name which the DimFilter required to do filter.
    99→   */
   100→  Set<String> getRequiredColumns();
   101→
   102→  /**
   103→   * Wrapper for {@link StringBuilder} to re-use common patterns in custom {@link DimFilter#toString()} implementations
   104→   */
   105→  class DimFilterToStringBuilder
   106→  {
   107→    private final StringBuilder builder;
   108→
   109→    public DimFilterToStringBuilder()
   110→    {
   111→      this.builder = new StringBuilder();
   112→    }
   113→
   114→    /**
   115→     * Append dimension name OR {@link ExtractionFn#toString()} with dimension wrapped in parenthesis
   116→     */
   117→    DimFilterToStringBuilder appendDimension(String dimension, @Nullable ExtractionFn extractionFn)
   118→    {
   119→      if (extractionFn != null) {
   120→        builder.append(extractionFn).append("(");
   121→      }
   122→
   123→      builder.append(dimension);
   124→
   125→      if (extractionFn != null) {
   126→        builder.append(")");
   127→      }
   128→      return this;
   129→    }
   130→
   131→    /**
   132→     * Add "=" expression
   133→     */
   134→    DimFilterToStringBuilder appendEquals(String value)
   135→    {
   136→      builder.append(" = ").append(value);
   137→      return this;
   138→    }
   139→
   140→    /**
   141→     * Add filter tuning to {@link #builder} if tuning exists
   142→     */
   143→    DimFilterToStringBuilder appendFilterTuning(@Nullable FilterTuning tuning)
   144→    {
   145→      if (tuning != null) {
   146→        builder.append(" (filterTuning=").append(tuning).append(")");
   147→      }
   148→
   149→      return this;
   150→    }
   151→
   152→    /**
   153→     * Generic passthrough to {@link StringBuilder#append}
   154→     */
   155→    <T> DimFilterToStringBuilder append(T s)
   156→    {
   157→      builder.append(s);
   158→      return this;
   159→    }
   160→
   161→    public String build()
   162→    {
   163→      return builder.toString();
   164→    }
   165→  }
   166→}
